CREATE TABLE organizations(id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE users(id uuid PRIMARY KEY, phone_hash text UNIQUE NOT NULL, phone_mask text NOT NULL);
CREATE TABLE entries(id text PRIMARY KEY, org_id text NOT NULL REFERENCES organizations(id), name text NOT NULL, open boolean NOT NULL DEFAULT true);
CREATE TABLE auth_sessions(token_hash text PRIMARY KEY, user_id uuid REFERENCES users(id), org_id text REFERENCES organizations(id), expires_at timestamptz NOT NULL, CHECK(user_id IS NOT NULL OR org_id IS NOT NULL));
CREATE TABLE otp_codes(phone_hash text PRIMARY KEY, code_hash text NOT NULL, sent_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, attempts int NOT NULL DEFAULT 0);
CREATE TABLE roles(id uuid PRIMARY KEY, org_id text NOT NULL REFERENCES organizations(id), name text NOT NULL, description text NOT NULL DEFAULT '', prompt text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','disabled')), published_version uuid, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE role_versions(id uuid PRIMARY KEY, role_id uuid NOT NULL REFERENCES roles(id), name text NOT NULL, description text NOT NULL, prompt text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE roles ADD FOREIGN KEY(published_version) REFERENCES role_versions(id);
CREATE TABLE sessions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), entry_id text NOT NULL REFERENCES entries(id), mode text NOT NULL DEFAULT 'formal' CHECK(mode IN ('formal','preview')), status text NOT NULL DEFAULT 'preparing' CHECK(status IN ('preparing','active','paused','recovery','closing','ended')), current_segment uuid, started_at timestamptz, deadline_at timestamptz, ended_at timestamptz, end_reason text, active_ms bigint NOT NULL DEFAULT 0, active_since timestamptz, heartbeat_at timestamptz, version int NOT NULL DEFAULT 0, epoch int NOT NULL DEFAULT 0, seq int NOT NULL DEFAULT 0, snapshot_version int NOT NULL DEFAULT 0, assessment_version int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_open_session ON sessions(user_id,entry_id) WHERE status <> 'ended' AND mode='formal';
CREATE INDEX deadlines ON sessions(deadline_at) WHERE status <> 'ended';
CREATE TABLE role_segments(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions(id), role_version_id uuid NOT NULL REFERENCES role_versions(id), start_seq int NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE sessions ADD FOREIGN KEY(current_segment) REFERENCES role_segments(id);
CREATE TABLE events(session_id uuid NOT NULL REFERENCES sessions(id), seq int NOT NULL, event_id uuid NOT NULL, kind text NOT NULL, speaker text NOT NULL CHECK(speaker IN ('user','assistant','system')), text text NOT NULL DEFAULT '', segment_id uuid REFERENCES role_segments(id), response_id uuid, epoch int, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,seq), UNIQUE(session_id,event_id));
CREATE TABLE snapshots(session_id uuid NOT NULL REFERENCES sessions(id), version int NOT NULL, covered_seq int NOT NULL, content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,version));
CREATE TABLE activities(id bigserial PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions(id), epoch int NOT NULL, started_at timestamptz NOT NULL, ended_at timestamptz, reason text);
CREATE TABLE chunks(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions(id), track text NOT NULL CHECK(track IN ('user','assistant','feedback')), chunk_no text NOT NULL, object_key text NOT NULL UNIQUE, checksum text NOT NULL, start_ms bigint NOT NULL, duration_ms int NOT NULL, sample_rate int NOT NULL, response_id uuid, epoch int NOT NULL, played_ms int NOT NULL DEFAULT 0, UNIQUE(session_id,track,chunk_no));
CREATE TABLE recording_assets(session_id uuid PRIMARY KEY REFERENCES sessions(id), object_key text, status text NOT NULL DEFAULT 'processing', missing jsonb NOT NULL DEFAULT '[]');
CREATE TABLE feedback(session_id uuid PRIMARY KEY REFERENCES sessions(id), rating int CHECK(rating BETWEEN 1 AND 5), tags jsonb NOT NULL DEFAULT '[]', text text NOT NULL DEFAULT '', skipped boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE retry_requests(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions(id), reason text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), review_reason text, used_by uuid UNIQUE REFERENCES sessions(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_pending_retry ON retry_requests(session_id) WHERE status='pending';
CREATE UNIQUE INDEX one_available_retry ON retry_requests(session_id) WHERE status='approved' AND used_by IS NULL;
CREATE TABLE assessments(session_id uuid NOT NULL REFERENCES sessions(id), version int NOT NULL, prompt text NOT NULL, status text NOT NULL DEFAULT 'pending', event_cutoff int NOT NULL, result jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,version));
CREATE TABLE human_reviews(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions(id), org_id text NOT NULL REFERENCES organizations(id), text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commands(actor text NOT NULL, request_id uuid NOT NULL, digest text NOT NULL, result jsonb NOT NULL, PRIMARY KEY(actor,request_id));
CREATE TABLE audit_logs(id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, target text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY, kind text NOT NULL, session_id uuid NOT NULL REFERENCES sessions(id), version int NOT NULL DEFAULT 0, state text NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), leased_at timestamptz, error text, UNIQUE(kind,session_id,version));
CREATE INDEX queue ON jobs(state,available_at);
